import React from 'react';
import { Link, type LinkProps } from 'react-router-dom';
import { demoAppUrl, pricingPath, SEO_HOME_PATH } from '../../constants/seoSite';

type Classable = { className?: string; children: React.ReactNode };

/** Link nội bộ @linm/fnb-seo — MemoryRouterSync → navigateToUrl khi mount shell */
export const SeoPricingLink: React.FC<Classable> = ({ className, children }) => (
  <Link to={pricingPath()} className={className}>
    {children}
  </Link>
);

export const SeoHomeLink: React.FC<Classable & Partial<Pick<LinkProps, 'onClick'>>> = ({
  className,
  children,
  onClick,
}) => (
  <Link to={SEO_HOME_PATH} className={className} onClick={onClick}>
    {children}
  </Link>
);

/** Link ra static @fnb-demo /demo/app-demo.html */
export const DemoAppLink: React.FC<Classable & React.AnchorHTMLAttributes<HTMLAnchorElement>> = ({
  className,
  children,
  ...rest
}) => (
  <a href={demoAppUrl()} className={className} {...rest}>
    {children}
  </a>
);
