import { isStandalone } from '../dev/isStandalone';

/** Tên demo / thương hiệu landing */
export const SEO_DEMO_NAME = 'Linm Soft';
/** Quán mẫu trong preview app (demo UI — không giới hạn phạm vi sản phẩm) */
export const SEO_PILOT_VENUE = 'Lẩu Gà Ngon';
export const SEO_PILOT_BRANCH = `${SEO_PILOT_VENUE} · Q1`;

/** @deprecated dùng SEO_DEMO_NAME */
export const SEO_TENANT_NAME = SEO_DEMO_NAME;
export const SEO_PLATFORM_NAME = SEO_DEMO_NAME;
export const SEO_BRAND_TITLE = SEO_DEMO_NAME;

/** @linm/fnb-seo — fragments/seo.json */
export const SEO_HOME_PATH = '/';
export const SEO_PRICING_PATH = '/pricing';

/** @fnb-demo static — fragments/demo.json deploySubpath */
export const DEMO_DEPLOY_SUBPATH = '/demo';
export const DEMO_APP_PAGE = 'app-demo.html';

export const SEO_CONTACT = {
  zaloLabel: 'Linm Soft',
  zaloUrl: 'https://zalo.me/0775909978',
  phone: '0775 909 978',
  phoneTel: '+84775909978',
};

export function seoBaseUrl(): string {
  const raw = (import.meta.env.VITE_SEO_BASE_URL || '').trim().replace(/\/$/, '');
  if (raw) return raw;
  if (typeof window !== 'undefined') {
    return `${window.location.origin}`;
  }
  return 'https://fnb-linm.com';
}

/** Base static demo — shell: /demo · standalone dev: http://localhost:9300 */
function resolveDemoBase(): string {
  const raw = (import.meta.env.VITE_FNB_DEMO_BASE || '').trim().replace(/\/$/, '');
  if (raw.startsWith('http')) return raw;
  if (raw) return raw.startsWith('/') ? raw : `/${raw}`;
  if (isStandalone && import.meta.env.DEV) {
    return 'http://localhost:9300';
  }
  return DEMO_DEPLOY_SUBPATH;
}

/** URL đầy đủ tới app-demo (static @fnb-demo) */
export function demoAppUrl(): string {
  const base = resolveDemoBase();
  const page = DEMO_APP_PAGE;
  if (base.startsWith('http')) {
    return `${base}/${page}`;
  }
  return `${base}/${page}`.replace(/\/{2,}/g, '/');
}

/** Route báo giá @linm/fnb-seo — dùng với Link / navigateToUrl */
export function pricingPath(): string {
  return SEO_PRICING_PATH;
}

/** @deprecated dùng demoAppUrl() */
export function demoBaseUrl(): string {
  return resolveDemoBase();
}

export function absoluteUrl(path: string): string {
  const base = seoBaseUrl();
  const p = path.startsWith('/') ? path : `/${path}`;
  return `${base}${p}`;
}
