import React from 'react';
import { HelmetProvider } from 'react-helmet-async';
import { MemoryRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { MarketingLayout } from './components/layout/MarketingLayout';
import { isStandalone, showDevNav } from './dev/isStandalone';
import { MemoryRouterSync } from './router/MemoryRouterSync';

const HomePage = React.lazy(() => import('./pages/marketing/HomePage'));
const PricingPage = React.lazy(() => import('./pages/marketing/PricingPage'));
const DevPage = React.lazy(() => import('./dev/DevPage'));

const Suspense: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <React.Suspense fallback={<div style={{ padding: '2rem' }}>Đang tải...</div>}>
    {children}
  </React.Suspense>
);

const initialPath =
  typeof window !== 'undefined' ? window.location.pathname + window.location.search || '/' : '/';

const AppRouter: React.FC = () => (
  <>
    <MemoryRouterSync />
    <Routes>
      <Route path="/" element={<MarketingLayout />}>
        <Route
          index
          element={
            <Suspense>
              <HomePage />
            </Suspense>
          }
        />
        <Route
          path="pricing"
          element={
            <Suspense>
              <PricingPage />
            </Suspense>
          }
        />
        {showDevNav && (
          <Route
            path="dev"
            element={
              <Suspense>
                <DevPage />
              </Suspense>
            }
          />
        )}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
  </>
);

const Root: React.FC = () => (
  <HelmetProvider>
    <Router initialEntries={[initialPath]} initialIndex={0}>
      <AppRouter />
    </Router>
  </HelmetProvider>
);

export default Root;
